# -*- coding: utf-8 -*-
# Обновление системного промта kip8test до post-Task 316
# (наведение/клик на дату шапки — подсветка ВСЕГО столбца +
#  фильтр окна мероприятий месяца по выбранному дню)
with open('Системный_промт_для_приложения_КИПиА.md', encoding='utf-8') as f:
    lines = f.readlines()

new3 = '''> **Версия документа:** 2026-09-04 (post-Task 316: НАВЕДЕНИЕ/КЛИК НА ДАТУ В ШАПКЕ ШАХМАТКИ — ВЫДЕЛЯЕТСЯ ВЕСЬ СТОЛБЕЦ (шапка + ячейки тела, вид как у «сегодня» Task 313), КЛИК ВЫБИРАЕТ ДЕНЬ И ФИЛЬТРУЕТ ОКНО МЕРОПРИЯТИЙ МЕСЯЦА ПО ЭТОМУ ДНЮ. СОДЕРЖАНИЕ: 1) НАВЕДЕНИЕ: мышь над датой шапки — столбец подсвечен (th.ws-day-col → ws-hover-col, td.ws-cell → ws-hover; градиент поверх фона th + inset-«заливка» ячеек ПОВЕРХ inline-цветов статусов — принцип «сегодня» Task 313, тон мягче), снимается уходом курсора (onmouseenter/onmouseleave → _dayHover); классы ставятся ПРЯМО в DOM (_dayColClass, без перерисовки — без мигания), _renderGrid штампует их из состояния (_hoverDay/_selDay) — подсветка/выбор ПЕРЕЖИВАЮТ перерисовку (правка/«Отменить»/«Обновить»). 2) КЛИК = ВЫБОР ДНЯ: клик по дате — ws-sel-col/ws-sel (насыщеннее наведения), окно мероприятий месяца (#wsEventsPanel Task 315) ФИЛЬТРУЕТСЯ по дню: показываются записи, НАКРЫВАЮЩИЕ дату (дата_начала <= день <= дата_окончания), заголовок «Мероприятия · 05.09 · N», пустой день — «нет мероприятий в этот день»; повторный клик по той же дате — сброс; клик по ЛЮБОЙ другой области (document-клик в CAPTURE-фазе, не зависит от stopPropagation попапов) — сброс; Esc — сброс; смена месяца/года (onMonthChange) — сброс; выбранный день вне месяца — охрана (полный месяц). 3) ДАТА КЛИКАБЕЛЬНА: th.ws-day-col cursor: pointer, th/td несут data-day; hover/выбор видны ВСЕМ ролям (зритель тоже фильтрует окно — прав не нужно). Сервер/листы/Apps Script НЕ менялись. Тесты: 1609 → 1629/0 (+20 test-task316.js; SW-бамп v554→v555 в 16 тест-файлах; поправлен assertFalse «лишний инкремент» в test-task315 — v556). Верификация: task316-browser-check.py 28/28 (3 контекста: десктоп-Админ [th[data-day] на всех днях, cursor pointer; hover: ws-hover-col на th + ws-hover на ВСЕХ td столбца, снятие при уходе; клик: ws-sel-col/ws-sel, окно «10.09 · 2» — только накрывающие записи, диапазоны живы; пустой день 17 — «нет мероприятий в этот день»; повторный клик — сброс; клик по окну времени — сброс; выбор переживает _renderGrid; светлая тема — тон 42,93,143; смена месяца — сброс+полный вид пустого месяца; 0 JS-ошибок], зритель «ИТР8 pro» [hover/клик/фильтр работают], мобильный 375px [клик по дате — столбец+фильтр]); регресс 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36 (C2 — таймингово-флейковый прогон, повторно 36/36 ×2), 315 33/33. ПЕРЕНОС В kip8: НЕ выполнен — Task 316 ожидает проверки пользователем в kip8test (после проверки — одним коммитом вместе с Task 315, kip8 v417→v418). Деплой пользователя: GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать.)
'''

assert lines[2].startswith('> **Версия документа:**')
lines.insert(2, new3 if new3.endswith('\n') else new3 + '\n')
print('Строка 3 вставлена (цепочка версий)')

src = ''.join(lines)

reps = [
    ('> **Текущая версия кэша:** `kipia-test-v554`',
     '> **Текущая версия кэша:** `kipia-test-v555`'),
    ('| `kip8test` | PWA | `kipia-test-v554` |',
     '| `kip8test` | PWA | `kipia-test-v555` |'),
]
for old, new in reps:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Версии кэша обновлены (2 замены)')

# Счётчики тестов
reps2 = [
    ('├── tests/                      # 1609 юнит-тестов (Node.js, 33 файлов): run-all.js, test-role-access.js, и др.',
     '├── tests/                      # 1629 юнит-тестов (Node.js, 34 файлов): run-all.js, test-role-access.js, и др.'),
    ('ожидается `1609 passed, 0 failed`', 'ожидается `1629 passed, 0 failed`'),
    ('# Ожидается: 1609 passed, 0 failed', '# Ожидается: 1629 passed, 0 failed'),
]
for old, new in reps2:
    n = src.count(old)
    assert n == 1, (old, n)
    src = src.replace(old, new)
print('Счётчики тестов обновлены (3 замены)')

# Буллет Task 316 — после буллета Task 315 (новые задачи ниже)
entry = ('\n- **График работы — наведение/клик на дату шапки: подсветка ВСЕГО столбца + фильтр окна мероприятий по дню (Task 316)**: '
         'по заявке пользователя (развитие «сегодня» Task 313 и окна мероприятий Task 315): 1) НАВЕДЕНИЕ: дата в шапке (th.ws-day-col, ВСЕ дни месяца, всем ролям) получает data-day + onmouseenter/onmouseleave → WorkSchedule._dayHover(d)/_dayHover(null): столбец подсвечивается ЦЕЛИКОМ — th получает ws-hover-col (linear-gradient поверх непрозрачного фона th + число акцентом — как «сегодня», тон мягче), ВСЕ td[data-day] столбца — ws-hover (inset-«заливка» box-shadow: inset 0 0 0 999px rgba(74,143,199,0.16) ПОВЕРХ inline-цветов статусов и планов; составные правила .ws-hover.ws-source-manual — рамка ручных д/н не затирается; светлая тема мягче: rgba(42,93,143,0.13)/0.10); уход курсора — подсветка снимается; классы ставятся ПРЯМО в DOM методом _dayColClass(d, thCls, cellCls, on) (toggle по th/td, БЕЗ перерисовки сетки — без мигания), а _renderGrid/_renderCell ШТАМПУЮТ их из состояния (_hoverDay/_selDay) — наведение/выбор переживают перерисовку (правка ячейки, «Отменить», «Обновить», перезагрузка данных). 2) КЛИК = ВЫБОР ДНЯ: onclick даты → _daySelect(d): th → ws-sel-col, td → ws-sel (НАСЫЩЕННЕЕ наведения: 0.30/0.24 тёмная, 0.20/0.15 светлая), окно мероприятий месяца #wsEventsPanel ПЕРЕРИСОВЫВАЕТСЯ с фильтром по дню: попадают записи листа «Инструктажи», НАКРЫВАЮЩИЕ дату (дата_начала <= ISO-дня <= дата_окончания — границы включительно), заголовок-плашка «Мероприятия · 05.09 · N» (день вместо месяца), пустой день — «нет мероприятий в этот день», диапазоны дат строк остаются («02–05.09» видно при выборе 03.09); повторный клик по ТОЙ ЖЕ дате — сброс (тоггл); клик по ЛЮБОЙ другой области — сброс: document-слушатель в init на CAPTURE-фазе (срабатывает раньше inline-обработчиков, не зависит от stopPropagation попапов; клик по th.ws-day-col пропускается — его разбирает onclick даты), т.е. клик по ячейке/тулбару/окнам/кнопкам/фону снимает выбор; Esc — сброс (в общем keydown); смена месяца/года — сброс (onMonthChange обнуляет _hoverDay/_selDay ДО loadGrid); выбранный день ВНЕ открытого месяца (31 у 30-дневного) — охрана в _renderMonthEventsPanel (selIso не собран → полный месяц). _daySelect(null) — программный сброс (no-op без выбора); выбор и фильтр доступны ВСЕМ ролям (зритель фильтрует окно — прав не нужно), hover/клик НЕ открывают попапы ячеек (для этого — клик по самой ячейке, как прежде). 3) КУРСОР: .ws-grid thead th.ws-day-col { cursor: pointer } — дата кликабельна с одного взгляда (принцип Task 311: назначение клика видно по курсору). td ячеек тоже несут data-day (селекторы столбца _dayColClass + штамповка классов в _renderCell). Сервер WorkSchedule.gs/листы/Apps Script/«Сформировать»/«Сохранить»/«Отменить»/кэш/бейджи/попапы/карточка — НЕ менялись. Верификация: сьют 1609→1629/0 (+20 tests/test-task316.js: HTML/JS [th data-day+хандлеры, штамповка классов, document-click capture, Esc, onMonthChange-сброс, состояние], CSS [градиенты th hover/sel, насыщенность sel>hover, inset td, составные с ws-source-manual, cursor pointer, светлая тема], VM [_dayHover: постановка/снятие/переход; _daySelect: выбор/тоггл/программный сброс/перерисовка окна; _renderMonthEventsPanel: фильтр накрывающих, граница диапазона включительно, пустой день, месяц без выбора, охрана дня вне месяца; _dayColClass: мягкий к мок-DOM], SW v555; поправлен test-task315 [assertFalse «лишний инкремент» v554→v556]; SW-бамп v554→v555 в 16 тест-файлах), task316-browser-check.py 28/28 (порт 8937, 3 контекста: десктоп-Админ — th[data-day=10] cursor pointer, td[data-day] на всех строках; hover: ws-hover-col на th + ws-hover на всех td, уход курсора — снято, hover не оставляет выбора; клик: ws-sel-col/ws-sel + градиент, окно «Мероприятия · 10.09 · 2» только накрывающие записи (Целевой+Пожарная), прочие скрыты; выбор ПЕРЕЖИВАЕТ _renderGrid; пустой день 17: переключение выбора + «нет мероприятий в этот день» + заголовок с днём; повторный клик — сброс (окно: весь месяц 5); клик по дате 12 — диапазон 12–15 накрывает (1); клик по окну времени — сброс; светлая тема — тон 42,93,143; смена месяца — классов нет, _selDay null, окно пустого месяца, возврат — 5 записей без выбора; 0 JS-ошибок; зритель «ИТР8 pro» — hover/клик/фильтр работают; мобильный 375px — клик по дате: столбец+фильтр), регресс 298 34/34, 303 20/20, 304 10/10, 305 20/20, 306 29/29, 307 20/20, 308 20/20, 309 26/26, 310 20/20, 311 24/24, 312 31/31, 313 30/30, 314 36/36 (один таймингово-флейковый прогон C2-спиннера, повторно 36/36 ×2 — гонка быстрого мок-fetch, не связано с Task 316), 315 33/33. SW kipia-test-v554→v555. ДЕПЛОЙ: только фронтенд — GitHub Pages + Ctrl+Shift+R ×1–2; Apps Script НЕ трогать — см. scripts/DEPLOY-Task316-day-column-highlight.md')
lines2 = src.split('\n')
insert_at = None
for i, l in enumerate(lines2):
    if l.startswith('- **График работы — бар из ТРЁХ РАВНЫХ частей'):
        j = i + 1
        while j < len(lines2) and lines2[j].startswith('  '):
            j += 1
        insert_at = j
        break
assert insert_at is not None, 'точка вставки (после буллета Task 315) не найдена'
lines2.insert(insert_at, entry)
src = '\n'.join(lines2)
print('Буллет Task 316 вставлен (после Task 315)')

with open('Системный_промт_для_приложения_КИПиА.md', 'w', encoding='utf-8') as f:
    f.write(src)
print('Промт обновлён: post-Task 316, кэш v555, тесты 1629/34')
